  else if (D) { S.omenU = D.p - DM.dread; S.whisperU = D.p - V4.whisper; }
  else if (t > 8) { const n = Math.floor((t - 8) / 70); S.omenU = t - 8 - n * 70 - 20 * hash2(n, 1, 3); S.whisperU = ((t - 34) % 70 + 70) % 70; }
  const w = (u, a, b, c, d) => u < -1 || u > 50 ? 0 : win(u, a, b, c, d);
  S.omen = w(S.omenU, 0, .45, 1.3, 2.6);                                       // rise .45 s, hold, release over 1.3 s+ (fear arrives fast, leaves slowly)
  S.whisper = w(S.whisperU, 0, .2, .9, 1.6);
  S.appar = w(S.apparU, 0, .6, 4.7, 5.9);                                      // the room drops (the first .6 s is stillness)
  S.still = w(S.apparU, 0, .3, .6, .9);                                        // everything holds its breath
  S.lid = w(S.apparU, .6, 1.3, 2.1, 2.6);                                      // Nut's sky peels open along the fracture; the colossal iris passes
  S.surf = w(S.apparU, 2.4, 2.9, 4.4, 4.9);                                    // the ORIGINAL presses to the breach
  S.bind = eIO(seg(S.apparU, 3.0, 3.9)) * (1 - eIO(seg(S.apparU, 4.5, 5.0)));  // the Puzzle's light draws the gold Wedjat over it
  S.kin = seg(S.apparU, 4.1, 4.5);                                             // ward-gold runs the breach's rim
  S.push = Math.max(w(S.omenU, .75, .95, 1.35, 2.2), w(S.apparU, 4.3, 4.45, 4.9, 5.8)); // the Puzzle flares: every eye squeezes shut
  S.relief = V4.DREAD ? seg(t - V4.d0, 14.2, 15.4) : 0;
  S.sg = Math.max(S.omen, S.appar * .9);
  S.drop = Math.max(.1 * S.whisper, .26 * S.omen, .6 * S.appar);               // the grade: each rung reads at arm's length
  return S;

